import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import Avatar from 'flarum/common/components/Avatar';
import username from 'flarum/common/helpers/username';
import extractText from 'flarum/common/utils/extractText';
import { openTeamManager } from './openers';
import { t } from '../util';
/** The team's ids, written back to the build so its page follows a change. */
export function setTeam(build, team) {
  build.pushData({
    relationships: {
      team: {
        data: team.map(member => ({
          type: 'garage-members',
          id: member.id()
        }))
      }
    }
  });
}

/** The build page's team, in the sidebar: the owner, then the members who accepted, each with a role. */
export default class BuildTeam extends Component {
  view() {
    const build = this.attrs.build;
    const members = build.team();
    const manages = build.canEdit() && build.published();
    if (!members.length && !manages) return null;
    return m("section", {
      className: "GarageTeam",
      "aria-label": extractText(t('team.heading'))
    }, m("h3", {
      className: "GarageSidebar-heading"
    }, m(Icon, {
      name: "fas fa-people-group"
    }), " ", t('team.heading')), m("ul", null, this.row(build.user(), t('team.owner')), members.map(member => this.row(member.user(), member.role()))), manages ? m(Button, {
      className: "Button Button--link GarageTeam-manage",
      icon: "fas fa-user-plus",
      onclick: () => openTeamManager({
        build
      })
    }, t(members.length ? 'team.manage' : 'team.invite_first')) : null);
  }
  row(user, role) {
    return m("li", {
      className: "GarageTeam-member"
    }, m(Link, {
      href: user ? app.route.user(user) : '#',
      className: "GarageTeam-link"
    }, m(Avatar, {
      user: user
    }), m("span", {
      className: "GarageTeam-who"
    }, m("span", {
      className: "GarageTeam-name"
    }, username(user)), role ? m("span", {
      className: "GarageTeam-role"
    }, role) : null)));
  }
}

/** The viewer's invite to the build's team, to accept or decline. */
export class TeamInvite extends Component {
  view() {
    const build = this.attrs.build;
    const membership = build.viewerMembership();
    if (!membership || membership.accepted()) return null;
    return m("div", {
      className: "GarageInvite"
    }, m(Icon, {
      name: "fas fa-user-plus"
    }), m("p", null, t(membership.role() ? 'team.invited_as' : 'team.invited_plain', {
      username: build.user()?.displayName(),
      role: membership.role()
    })), m("div", {
      className: "GarageInvite-actions"
    }, m(Button, {
      className: "Button Button--primary",
      onclick: () => this.answer(membership, true)
    }, t('team.accept')), m(Button, {
      className: "Button",
      onclick: () => this.answer(membership, false)
    }, t('team.decline'))));
  }
  answer(membership, accept) {
    const build = this.attrs.build;
    const done = accept ? membership.save({
      status: 'accepted'
    }) : membership.delete();

    // A declined invite is gone from the store, so viewerMembership() reads null again.
    done.then(() => {
      if (accept) setTeam(build, [...build.team(), membership]);
      m.redraw();
    });
  }
}

/** The build's Manage menu: the team window (the owner, a moderator), or Leave team (a member). */
export function teamControls(build, items) {
  const membership = build.viewerMembership();
  if (build.canEdit() && build.published()) {
    items.add('team', m(Button, {
      icon: "fas fa-people-group",
      onclick: () => openTeamManager({
        build
      })
    }, t('team.manage')), 90);
  }
  if (membership?.accepted()) {
    items.add('leave', m(Button, {
      icon: "fas fa-right-from-bracket",
      onclick: () => leave(build, membership)
    }, t('team.leave')), 50);
  }
}
function leave(build, membership) {
  if (!confirm(extractText(t('team.leave_confirm')))) return;
  membership.delete().then(() => {
    setTeam(build, build.team().filter(member => member !== membership));
    m.redraw();
  });
}
flarum.reg.add('ernestdefoe-garage', 'forum/components/BuildTeam', BuildTeam);